LINEAGE A:  { READ-ALL, BACKUP }       ---->  { READ-ALL }
                                                   |
                                                   |  cross-lineage composition (bug)
                                                   v
LINEAGE B:  { READ-FOO, SHARE-FILES }  ---->  { SHARE-FILES }  ---->  { READ-ALL, SHARE-FILES }
                                                                         EXECUTOR n+1

{
  "issuer": "did:example:users:alice",
  "invariants": {
    "operations": ["READ-ALL", "BACKUP"],
    "executionContract": {
      "role": "backup-service",
      "compliance": ["GDPR"],
      "serviceAgreements": [
        "https://legal.example.com/agreements/dpa-2026-001"
      ],
      "executionModel": "deterministic"
    }
  },
  "continuation": {
    "challenge": "base64url-random-256-bit-value",
    "mode": "single-use",
    "expiresAt": "2026-07-17T10:05:00Z"
  },
  "issuedAt": "2026-07-17T10:00:00Z",
  "expiresAt": "2026-07-18T10:00:00Z"
}

{
  "issuer": "did:example:users:alice",
  "invariants": {
    "operations": ["READ-FOO", "SHARE-FILES"],
    "executionContract": {
      "role": "summary-service",
      "serviceAgreements": [
        "https://legal.acme.example/agreements/asa-2026-042"
      ],
      "executionModel": "agentic"
    }
  },
  "continuation": {
    "challenge": "base64url-random-256-bit-value",
    "mode": "single-use",
    "expiresAt": "2026-07-17T10:05:00Z"
  },
  "issuedAt": "2026-07-17T10:00:00Z",
  "expiresAt": "2026-07-18T10:00:00Z"
}

{
  "type": "PIC-PoR-v0",
  "predecessorReference": "profile-defined cryptographic reference",
  "continuationResponse": {
    "predecessorChallenge": "base64url... (from the predecessor's continuation)",
    "executorNonce": "base64url-random-256-bit-value"
  },
  "executor": "did:example:workloads:eu:backup-service",
  "request": {
    "operation": "BACKUP",
    "target": "eu-1/tenant-42/dataset/backups",
    "securityDomain": "tenant-42",
    "requestDigest": "sha256:...",
    "payloadDigest": "sha256:..."
  },
  "executorAttestation": {
    "subject": "did:example:workloads:eu:backup-service",
    "attributes": {
      "role": "backup-service",
      "compliance": ["GDPR"],
      "accountableParty": "Example Corp",
      "serviceAgreements": [
        "https://legal.example.com/agreements/dpa-2026-001"
      ],
      "environment": "production",
      "region": "eu-1",
      "availabilityZone": "eu-1a",
      "executionModel": "deterministic"
    },
    "issuedAt": "2026-07-17T10:00:00Z",
    "expiresAt": "2026-08-17T10:00:00Z",
    "issuer": "did:example:org-authority"
  }
}

{
  "operations": ["READ-ALL"],
  "executionContract": {
    "role": "backup-service",
    "compliance": ["GDPR"],
    "serviceAgreements": [
      "https://legal.example.com/agreements/dpa-2026-001"
    ],
    "executionModel": "deterministic"
  }
}

{
  "predecessorReference": "profile-defined cryptographic reference",
  "proofOfRelationship": { "...": "profile-defined PoR" },
  "attenuation": { "...": "profile-defined authority attenuation" },
  "nextFreshness": { "...": "profile-defined next challenge or equivalent" },
  "requestBinding": { "...": "profile-defined request/execution binding" },
  "signatureOrProof": { "...": "profile-defined integrity protection" }
}

list.t:
execution-contract conformance — when the predecessor authority context contains an execution contract and the selected profile
requires executor conformance evidence, the presented executor or evidence satisfies that contract according to the profile-defined
conformance function (Section 4); for example a deterministic contract rejects an agentic executor;

